export function icon(name, cls = 'ico') {
  const body = SHAPES[name] || SHAPES.apps;
  return `<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true">${body}</svg>`;
}

export const ICON_NAMES = Object.keys(SHAPES);
